const holds = new Set();
const hold = async (room) => { holds.add(room); };
const release = async (room) => { holds.delete(room); };
const takeDeposit = async (room) => {
  if (room === "suite") throw new Error("deposit declined");
  return `deposit for ${room}`;
};

async function book(room) {
  await hold(room);
  try {
    return await takeDeposit(room);
  } catch (error) {
    await release(room);
    throw error;
  }
}

console.log(await book("single"), [...holds]);
try {
  await book("suite");
} catch (error) {
  console.log(error.message, [...holds]);
}

