const products = [
  { sku: "rice-5kg", price: 9500 },
  { sku: "oil-1l", price: 3200 },
  { sku: "beans-2kg", price: 4800 },
];

function query() {
  const filters = [];
  return {
    where(test) {
      filters.push(test);
      return this;
    },
    then(resolve) {
      resolve(products.filter((p) => filters.every((f) => f(p))));
    },
  };
}

const cheap = await query().where((p) => p.price < 5000);
console.log(cheap.map((p) => p.sku));

