const cache = new Map([["rice-5kg", 9500]]);
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function getPrice(sku) {
  if (cache.has(sku)) return cache.get(sku);
  await wait(10);
  return 4800;
}

for (const sku of ["rice-5kg", "beans-2kg"]) {
  let step = "before";
  getPrice(sku).then((price) => console.log(sku, price, step));
  step = "after";
}
